"""Input constructors only; no receive, PN-reconstruction or canonicalization model."""
def v(value,width=None):
    if width is None:width=next(w for w in [1,2,4,8] if value<2**(8*w-2))
    if width not in [1,2,4,8] or not 0<=value<2**(8*width-2):raise ValueError('varint')
    return (([1,2,4,8].index(width)<<(8*width-2))|value).to_bytes(width,'big')
def envelope(level,pn,body,cid=b'\xaa',scid=b'\xbb',token=b'',width=1,phase=0,spin=0,length_width=None):
    number=(pn%(2**(8*width))).to_bytes(width,'big')
    if level=='A':return bytes([0x40|(spin<<5)|(phase<<2)|(width-1)])+cid+number+body
    head=bytes([(0xc0 if level=='I' else 0xe0)|(width-1)])+b'\0\0\0\1'+bytes([len(cid)])+cid+bytes([len(scid)])+scid
    if level=='I':head+=v(len(token))+token
    return head+v(width+len(body),length_width)+number+body
def stream(sid,off,data,fin=False,offset=True,length=True):
    return bytes([8|(4 if offset else 0)|(2 if length else 0)|int(fin)])+v(sid)+(v(off) if offset else b'')+(v(len(data)) if length else b'')+data
def crypto(off,data):return b'\x06'+v(off)+v(len(data))+data
def datagram(wire,auth=(0,)):return {'datagram':{'wire':wire.hex(),'auth':list(auth)}}
def trace(events,connection=2**62-1,stream_credit=2**62-1,bidi=2**60,uni=2**60,cids=4,local_bidi=2,local_uni=2,local_cids=('aa','bb'),received=None):
    return {'limits':{'connection':connection,'stream':stream_credit,'bidi':bidi,'uni':uni,'cids':cids},'local':{'bidi':local_bidi,'uni':local_uni,'cids':list(local_cids)},'peer':{'cid':'cc','token':'00'*16},'received':received or {'I':None,'H':None,'A':None},'events':events}
"""Visible scored-process profile: Java threads are allowed, child processes are not."""
import ctypes,errno,os,platform,resource,signal,sys

def restrict(cpu=60):
    if os.geteuid()==0 or platform.machine()!='x86_64':raise RuntimeError('nonroot Linux x86_64 required')
    for key,pair in [(resource.RLIMIT_AS,(4*1024**3,)*2),(resource.RLIMIT_CPU,(cpu,cpu+1)),(resource.RLIMIT_NOFILE,(128,128)),(resource.RLIMIT_NPROC,(64,64)),(resource.RLIMIT_FSIZE,(64*1024**2,)*2),(resource.RLIMIT_CORE,(0,0))]:resource.setrlimit(key,pair)
    class Filter(ctypes.Structure):_fields_=[('code',ctypes.c_ushort),('jt',ctypes.c_ubyte),('jf',ctypes.c_ubyte),('k',ctypes.c_uint32)]
    class Program(ctypes.Structure):_fields_=[('len',ctypes.c_ushort),('filter',ctypes.POINTER(Filter))]
    rows=[(0x20,0,0,4),(0x15,1,0,0xc000003e),(0x06,0,0,0x80000000),(0x20,0,0,0),(0x35,0,1,0x40000000),(0x06,0,0,0x80000000)]
    denied=[41,42,29,30,31,64,65,66,220,68,69,70,71,62,200,234,101,310,311,272,308,165,166,155,161,112,109,105,106,113,114,117,119,116,304,303,321,250,248,249,298,323,425,426,427,438,57,58]
    for n in denied:rows.extend([(0x15,0,1,n),(0x06,0,0,0x50000|errno.EPERM)])
    # JDK NIO uses a local AF_UNIX pair for its pre-close descriptor.
    rows.extend([(0x15,0,4,53),(0x20,0,0,16),(0x15,1,0,1),
                 (0x06,0,0,0x50000|errno.EPERM),(0x20,0,0,0)])
    # clone3 returns ENOSYS; clone is limited to threads, without namespaces.
    rows.extend([(0x15,0,1,435),(0x06,0,0,0x50000|errno.ENOSYS),
                 (0x15,0,6,56),(0x20,0,0,16),(0x45,1,0,0x10000),(0x06,0,0,0x50000|errno.EPERM),
                 (0x45,0,1,0x7e820000),(0x06,0,0,0x50000|errno.EPERM),(0x20,0,0,0),
                 (0x06,0,0,0x7fff0000)])
    array=(Filter*len(rows))(*(Filter(*r) for r in rows));prog=Program(len(rows),array)
    libc=ctypes.CDLL(None,use_errno=True)
    for option,value in [(4,0),(38,1)]:
        if libc.prctl(option,value,0,0,0):raise OSError(ctypes.get_errno(),'prctl')
    if libc.prctl(22,2,ctypes.byref(prog),0,0):raise OSError(ctypes.get_errno(),'seccomp')
    signal.pthread_sigmask(signal.SIG_UNBLOCK,{signal.SIGINT,signal.SIGTERM})

if __name__=='__main__':
    restrict()
    os.environ['MALLOC_ARENA_MAX']='2'
    os.environ['LD_LIBRARY_PATH']='/opt/java/lib/jli:/opt/java/lib:/opt/java/lib/server'
    if len(sys.argv)>1 and sys.argv[1]=='--exec':
        os.execv(sys.argv[2],sys.argv[2:])
    os.execv('/opt/java/bin/java',['/opt/java/bin/java','-Djava.io.tmpdir=/workspace/tmp','-XX:ActiveProcessorCount=2','-XX:+UseSerialGC','-XX:+DisableAttachMechanism','-Xms32m','-Xmx1024m','-Xss512k','-XX:CompressedClassSpaceSize=64m','-XX:ReservedCodeCacheSize=64m','-cp',sys.argv[1],'offline.Main'])
